# Reversing leg 1: navigating the bend with proper steering sense
state = {'clearing': True}

def control(obs):
    target_look = -23.0
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    if hold_s > 0.05:
        return (0.0, 0.0, target_look)

    progress = obs.get('progress', {})
    rev_covered = progress.get('covered', 0.0)
    hitch = obs.get('hitch_deg', 0.0)

    # Phase 1: Pull forward to clear pinned rear-left corner
    if state['clearing']:
        if rev_covered > 6.0:
            return (0.0, 0.8, target_look)
        else:
            state['clearing'] = False

    # Phase 2: Reverse into the right turn
    views = obs.get('views', {})
    cam = views.get('camera', {})
    walls = cam.get('walls', [])

    left_dists = [d for b, d in walls if 100 < b < 175]
    right_dists = [d for b, d in walls if -175 < b < -100]
    min_l = min(left_dists) if left_dists else 1.5
    min_r = min(right_dists) if right_dists else 1.5

    target_hitch = -15.0 + (min_l - min_r) * 10.0
    target_hitch = max(-25.0, min(10.0, target_hitch))

    hitch_err = hitch - target_hitch
    steer = max(-32.0, min(32.0, hitch_err * 2.5))

    return (steer, -0.5, target_look)

