import math

phase = 'pull_forward'
t_start = None

def control(obs):
    global phase, t_start
    t = obs.get('t', 0.0)
    if t_start is None:
        t_start = t

    look_deg = 160.0
    hitch = obs.get('hitch_deg', 0.0)
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)

    # Phase 1: Pull forward slightly to the left to clear the right rail and recenter
    if phase == 'pull_forward':
        if hold_s > 0:
            return {'steer_deg': 20.0, 'speed_mps': 0.0, 'look_deg': look_deg}
        # Move forward about 1.5 - 2 meters
        if t - t_start < 4.0:
            # Steer slightly left (+20 deg) while moving forward
            return {'steer_deg': 20.0, 'speed_mps': 0.6, 'look_deg': look_deg}
        else:
            phase = 'reverse'

    # Phase 2: Reverse carefully into bay
    left_points = []
    right_points = []

    views = obs.get('views', {})
    for vname, vdata in views.items():
        orig = vdata.get('origin', [0.1, 0.0])
        for b_deg, dist in vdata.get('walls', []):
            rad = math.radians(b_deg)
            px = orig[0] + dist * math.cos(rad)
            py = orig[1] + dist * math.sin(rad)
            if px < 1.0:
                if py > 0:
                    left_points.append((px, py))
                else:
                    right_points.append((px, py))

    rear_x = obs.get('rig', {}).get('trailer_rear', [-1.6, 0.0])[0]

    # Look at points near trailer rear
    min_left = 999.0
    for px, py in left_points:
        if abs(px - rear_x) < 2.0:
            if py < min_left:
                min_left = py

    min_right = 999.0
    for px, py in right_points:
        if abs(px - rear_x) < 2.0:
            if -py < min_right:
                min_right = -py

    # Bay corners if seen
    bay_corners = []
    for vname, vdata in views.items():
        orig = vdata.get('origin', [0.1, 0.0])
        for b_deg, dist in vdata.get('target_corners', []):
            rad = math.radians(b_deg)
            px = orig[0] + dist * math.cos(rad)
            py = orig[1] + dist * math.sin(rad)
            bay_corners.append((px, py))

    lateral_err = 0.0
    if bay_corners:
        avg_bay_y = sum(p[1] for p in bay_corners) / len(bay_corners)
        # Trailer rear y is obs['rig']['trailer_rear'][1]
        trailer_y = obs.get('rig', {}).get('trailer_rear', [-1.6, 0.0])[1]
        # If trailer_y > avg_bay_y, trailer is too far left, lateral_err > 0
        lateral_err = trailer_y - avg_bay_y
    elif min_left < 100.0 and min_right < 100.0:
        # Positive lateral_err means closer to left rail (too far left)
        lateral_err = (min_right - min_left) / 2.0
    elif min_right < 1.0:
        # Too close to right rail!
        lateral_err = -(1.0 - min_right)
    elif min_left < 1.0:
        lateral_err = (1.0 - min_left)

    # Target hitch angle: gently nudge towards center
    target_hitch = -lateral_err * 12.0
    target_hitch = max(-10.0, min(10.0, target_hitch))

    hitch_err = hitch - target_hitch
    steer = hitch_err * 2.2
    steer = max(-35.0, min(35.0, steer))

    speed = -0.35  # Slower speed for precise bay entry
    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look_deg}

