import math

forward_done = False
t_fwd_start = None

def control(obs):
    global forward_done, t_fwd_start
    t = obs.get('t', 0.0)
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    status = obs.get('status', '')

    # If we haven't completed the forward move yet:
    if not forward_done:
        if hold_s > 0:
            # Waiting for penalty or gear change
            return {'steer_deg': 25.0, 'speed_mps': 0.0, 'look_deg': 160.0}

        if t_fwd_start is None:
            t_fwd_start = t

        # Move forward for 3.0 seconds at +0.7 m/s
        if t - t_fwd_start < 3.0:
            return {'steer_deg': 25.0, 'speed_mps': 0.7, 'look_deg': 160.0}
        else:
            # Before switching to reverse, brake to 0
            if t - t_fwd_start < 3.5:
                return {'steer_deg': 0.0, 'speed_mps': 0.0, 'look_deg': 160.0}
            forward_done = True

    # Reversing phase
    if hold_s > 0:
        return {'steer_deg': 0.0, 'speed_mps': 0.0, 'look_deg': 160.0}

    look_deg = 160.0

    views = obs.get('views', {})
    bay_corners = []
    left_points = []
    right_points = []

    for vname, vdata in views.items():
        orig = vdata.get('origin', [0.1, 0.0])
        for b_deg, dist in vdata.get('target_corners', []):
            rad = math.radians(b_deg)
            bay_corners.append((orig[0] + dist * math.cos(rad), orig[1] + dist * math.sin(rad)))
        for b_deg, dist in vdata.get('walls', []):
            rad = math.radians(b_deg)
            px = orig[0] + dist * math.cos(rad)
            py = orig[1] + dist * math.sin(rad)
            if px < 1.0:
                if py > 0:
                    left_points.append((px, py))
                else:
                    right_points.append((px, py))

    rear_x = obs.get('rig', {}).get('trailer_rear', [-1.6, 0.0])[0]
    trailer_y = obs.get('rig', {}).get('trailer_rear', [-1.6, 0.0])[1]

    min_left = 999.0
    for px, py in left_points:
        if abs(px - rear_x) < 2.0 and py < min_left:
            min_left = py

    min_right = 999.0
    for px, py in right_points:
        if abs(px - rear_x) < 2.0 and -py < min_right:
            min_right = -py

