state = 'HOLD'
t_start = None

def control(obs):
    global state, t_start
    t = obs.get('t', 0.0)
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    look_deg = 160.0

    if t_start is None:
        t_start = t

    # Phase 1: Wait out penalty
    if state == 'HOLD':
        if hold_s <= 0 and (t - t_start > 5.2):
            state = 'PULL_FORWARD'
            t_start = t
        else:
            return {'steer_deg': -10.0, 'speed_mps': 0.0, 'look_deg': look_deg}

    # Phase 2: Pull forward ~1.0m steered slightly right (-8 deg)
    # to pull trailer forward and bias it left without vehicle front hitting left rail
    if state == 'PULL_FORWARD':
        dt = t - t_start
        if dt < 2.0:
            return {'steer_deg': -8.0, 'speed_mps': 0.45, 'look_deg': look_deg}
        elif dt < 2.7:
            return {'steer_deg': -12.0, 'speed_mps': 0.0, 'look_deg': look_deg}
        else:
            state = 'REVERSE'
            t_start = t

    # Phase 3: Reverse into the bay
    # We have 8/8 touches, so zero tolerance for error!
    # To keep trailer rear away from right rail, maintain positive hitch (+12 deg)
    # until entering the bay, then straighten up.
    if state == 'REVERSE':
        if hold_s > 0:
            return {'steer_deg': -12.0, 'speed_mps': 0.0, 'look_deg': look_deg}

        rem = obs.get('progress', {}).get('remaining', 3.4)
        if rem > 1.0:
            target_hitch = 13.0
        else:
            target_hitch = 0.0

        hitch_err = hitch - target_hitch
        steer = hitch_err * 2.5
        steer = max(-25.0, min(25.0, steer))

        return {'steer_deg': steer, 'speed_mps': -0.2, 'look_deg': look_deg}

