import math

state = {
    'forward_target_m': 6.0,
    'forward_start_progress': None,
    'phase': 'unpin_forward'
}

def control(obs):
    look_deg = -41.0
    status = obs.get('status', '')
    progress = obs.get('progress', {})
    covered = progress.get('covered', 61.4)
    rem = progress.get('remaining', 20.6)
    hitch = obs.get('hitch_deg', 0.0)

    if state['phase'] == 'unpin_forward':
        if state['forward_start_progress'] is None:
            state['forward_start_progress'] = covered
        pulled = state['forward_start_progress'] - covered
        if pulled < state['forward_target_m']:
            return {'steer_deg': -20.0, 'speed_mps': 1.2, 'look_deg': look_deg}
        else:
            state['phase'] = 'reverse'

    views = obs.get('views', {})
    cam = views.get('camera')
    left_clearance = 99.0
    right_clearance = 99.0

    if cam and 'walls' in cam:
        for b_deg, d in cam['walls']:
            b_rad = math.radians(b_deg)
            y = d * math.sin(b_rad)
            x = d * math.cos(b_rad)
            if x < 0 and abs(x) < 8.0:
                if y > 0:
                    side_d = y - 1.275
                    if side_d < left_clearance:
                        left_clearance = side_d
                else:
                    side_d = (-y) - 1.275
                    if side_d < right_clearance:
                        right_clearance = side_d

    diff = left_clearance - right_clearance
    target_hitch = max(-10.0, min(10.0, diff * 6.0))
    if rem < 4.0:
        target_hitch = 0.0

    hitch_err = hitch - target_hitch
    steer = hitch_err * 2.8 + hitch * 0.5
    steer = max(-35.0, min(35.0, steer))
    speed = -0.7 if rem < 8.0 else -0.9
    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look_deg}

