import math

state = {
    'mode': 'pull_forward',
    'start_covered': None,
    'target_pull_m': 3.5
}

def control(obs):
    look_deg = -41.0
    hitch = obs.get('hitch_deg', 0.0)
    progress = obs.get('progress', {})
    covered = progress.get('covered', 62.7)
    rem = progress.get('remaining', 19.3)

    # Phase 1: Pull forward to give room
    if state['mode'] == 'pull_forward':
        if state['start_covered'] is None:
            state['start_covered'] = covered
        pulled = state['start_covered'] - covered
        if pulled < state['target_pull_m']:
            return {'steer_deg': -8.0, 'speed_mps': 0.8, 'look_deg': look_deg}
        else:
            state['mode'] = 'reverse'

    # Phase 2: Reverse into the bay
    # We touched rear-left at +166°/1.2m while hitch was -11.7°.
    # In the trailer frame, when hitch is -11.7°, heading is -168°.
    # The corner at +166° is on the outside of the turn.
    # If the hitch angle is too negative, the trailer rotates too sharply or sweeps wide.
    # Maintain a shallower curve: target_hitch around -16° to -20°.
    target_hitch = -18.0 if rem > 8.0 else (-8.0 if rem > 4.0 else 0.0)

    views = obs.get('views', {})
    cam = views.get('camera')
    if cam and 'walls' in cam and cam['walls']:
        left_d = 99.0
        right_d = 99.0
        for b_deg, d in cam['walls']:
            b_rad = math.radians(b_deg)
            y = d * math.sin(b_rad)
            x = d * math.cos(b_rad)
            if x < 0 and abs(x) < 6.0:
                if y > 0:
                    left_d = min(left_d, y - 1.275)
                else:
                    right_d = min(right_d, (-y) - 1.275)
        if left_d < 1.5:
            # Too close to left rail, need trailer to go right (hitch more negative)
            target_hitch -= (1.5 - left_d) * 8.0
        elif right_d < 1.5:
            target_hitch += (1.5 - right_d) * 8.0

    target_hitch = max(-26.0, min(5.0, target_hitch))

    hitch_err = hitch - target_hitch
    steer = hitch_err * 2.5 + hitch * 0.3
    steer = max(-35.0, min(35.0, steer))

    speed = -0.6 if rem < 8.0 else -0.8
    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look_deg}

