import math

state = {
    'mode': 'pull_forward',
    'start_covered': None,
    'target_pull_m': 5.0
}

def control(obs):
    look_deg = -41.0
    hitch = obs.get('hitch_deg', 0.0)
    progress = obs.get('progress', {})
    covered = progress.get('covered', 63.8)
    rem = progress.get('remaining', 18.2)

    # Phase 1: Pull forward 5m steered right to pull the entire rig into the bay's entrance lane
    if state['mode'] == 'pull_forward':
        if state['start_covered'] is None:
            state['start_covered'] = covered
        pulled = state['start_covered'] - covered
        if pulled < state['target_pull_m']:
            # Pull forward with steer=-18 deg to swing the trailer cleanly rightward
            return {'steer_deg': -18.0, 'speed_mps': 0.65, 'look_deg': look_deg}
        else:
            state['mode'] = 'reverse'

    # Phase 2: Reverse into bay
    # Target is straight into the bay along -145 to -150 deg (hitch ~ -30 deg to align cab & trailer)
    # With max touches (8/8 reached or close), we must proceed with extreme precision.
    views = obs.get('views', {})
    cam = views.get('camera')

    target_hitch = -28.0
    if rem < 5.0:
        target_hitch = -10.0
    elif rem < 2.0:
        target_hitch = 0.0

    if cam and 'walls' in cam and cam['walls']:
        trailer_hdg = math.radians(-180.0 - hitch)
        cos_th = math.cos(-trailer_hdg)
        sin_th = math.sin(-trailer_hdg)

        min_l = 99.0
        min_r = 99.0
        for b_deg, d in cam['walls']:
            b_rad = math.radians(b_deg)
            xv = d * math.cos(b_rad)
            yv = d * math.sin(b_rad)
            # In trailer frame
            xt = xv * cos_th - yv * sin_th
            yt = xv * sin_th + yv * cos_th
            if -6.0 < xt < 0.5:
                if yt > 0:
                    min_l = min(min_l, yt - 1.275)
                else:
                    min_r = min(min_r, (-yt) - 1.275)

        if min_l < 1.2:
            target_hitch -= (1.2 - min_l) * 20.0
        elif min_r < 0.8:
            target_hitch += (0.8 - min_r) * 15.0

    target_hitch = max(-35.0, min(-5.0, target_hitch))

    hitch_err = hitch - target_hitch
    steer = hitch_err * 2.5 + hitch * 0.35
    steer = max(-35.0, min(35.0, steer))

    speed = -0.35
    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': look_deg}

